package dev.industrialtechnology.solar;
import dev.industrialtechnology.capacitor.BankLedger;import dev.industrialtechnology.expansion.ExpansionConfig;import cofh.api.energy.*;import net.minecraftforge.common.util.ForgeDirection;import net.minecraft.tileentity.TileEntity;import net.minecraft.nbt.NBTTagCompound;
public final class TileSolar extends TileEntity implements IEnergyProvider {
 private long savedEnergy;public BankLedger.Cell cell;SolarArrays.Array array;public boolean sky;public int generated;long skyAt=Long.MIN_VALUE,generatedAt=Long.MIN_VALUE;
 public int tier(){return worldObj!=null&&getBlockType() instanceof BlockSolar?((BlockSolar)getBlockType()).tier:0;}public int rate(){return ExpansionConfig.solar[tier()];}
 public BankLedger.Cell cell(){if(cell==null||cell.capacity!=(long)rate()*200)cell=new BankLedger.Cell((long)rate()*200,cell==null?savedEnergy:cell.energy(),()->markDirty());return cell;}
 @Override public boolean canUpdate(){return false;}@Override public void validate(){super.validate();if(worldObj!=null&&!worldObj.isRemote)SolarArrays.attach(this);}
 public void detach(){if(worldObj!=null&&!worldObj.isRemote)SolarArrays.detach(this);}@Override public void invalidate(){detach();super.invalidate();}@Override public void onChunkUnload(){detach();super.onChunkUnload();}
 public void changed(){skyAt=Long.MIN_VALUE;if(worldObj!=null&&!worldObj.isRemote)SolarArrays.dirty(worldObj);}
 public SolarArrays.Array network(){return worldObj==null||worldObj.isRemote||isInvalid()?null:SolarArrays.network(this);}
 public double sun(){long n=worldObj.getTotalWorldTime();if(skyAt==Long.MIN_VALUE||n-skyAt>=20){sky=worldObj.canBlockSeeTheSky(xCoord,yCoord+1,zCoord);skyAt=n;}return Sunlight.factor(worldObj.getWorldTime(),sky,!worldObj.provider.hasNoSky,worldObj.isRaining(),worldObj.isThundering(),ExpansionConfig.rain,ExpansionConfig.thunder,ExpansionConfig.daylight);}
 @Override public int extractEnergy(ForgeDirection d,int n,boolean sim){SolarArrays.Array a=network();return a==null||!a.valid||a.busy||d==ForgeDirection.UP||d==ForgeDirection.UNKNOWN?0:a.ledger.extract(n,worldObj.getTotalWorldTime(),a.limit,sim);}
 @Override public boolean canConnectEnergy(ForgeDirection d){return d!=ForgeDirection.UP&&d!=ForgeDirection.UNKNOWN;}@Override public int getEnergyStored(ForgeDirection d){SolarArrays.Array a=network();return a==null?0:(int)Math.min(Integer.MAX_VALUE,a.ledger.stored());}@Override public int getMaxEnergyStored(ForgeDirection d){SolarArrays.Array a=network();return a==null?0:(int)Math.min(Integer.MAX_VALUE,a.ledger.capacity());}
 public NBTTagCompound snapshot(){NBTTagCompound n=new NBTTagCompound();SolarArrays.Array a=network();double s=sun();n.setString("Title",getBlockType().getLocalizedName());n.setInteger("Tier",tier()+1);n.setInteger("Generation",generated);n.setInteger("Peak",rate());n.setInteger("Sun",(int)(100*s));n.setBoolean("Sky",sky);n.setInteger("Panels",a==null?1:a.members.size());n.setLong("ArrayRF",a==null?0:a.generation);n.setLong("Energy",a==null?0:a.ledger.stored());n.setString("Status",!sky?"SKY OBSTRUCTED":s==0?"NIGHT / NO SUN":"GENERATING");return n;}
 @Override public void writeToNBT(NBTTagCompound n){super.writeToNBT(n);n.setLong("SolarRF",cell().energy());n.setLong("GenerationTick",generatedAt);}@Override public void readFromNBT(NBTTagCompound n){super.readFromNBT(n);savedEnergy=n.getLong("SolarRF");generatedAt=n.hasKey("GenerationTick")?n.getLong("GenerationTick"):Long.MIN_VALUE;cell=null;}
}
